package com.pharmapack.qms.qa; import com.pharmapack.qms.audit.AuditTrailService; import com.pharmapack.qms.batch.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/qa-reviews") public class QAReviewController { final QAReviewRepository rr; final BatchRepository br; final AuditTrailService at; public QAReviewController(QAReviewRepository r,BatchRepository b,AuditTrailService a){rr=r;br=b;at=a;} @GetMapping public List<QAReviewResponse> list(){return rr.findAll().stream().map(this::dto).toList();} public record Create(Long batchId,Long reviewerId,String reviewType,String decision,String comments){}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public QAReviewResponse create(@RequestBody Create x){QAReview q=new QAReview();q.setBatch(br.findById(x.batchId()).orElseThrow(()->new IllegalArgumentException("Batch not found")));q.setReviewerId(x.reviewerId());q.setReviewType(x.reviewType());q.setDecision(x.decision()==null?"PENDING":x.decision());q.setComments(x.comments());q.setReviewDate(LocalDateTime.now());QAReview saved=rr.save(q);at.log("CREATE","QAReview",saved.getId(),"decision",null,saved.getDecision());return dto(rr.findById(saved.getId()).orElseThrow());}
 QAReviewResponse dto(QAReview q){var b=q.getBatch();return new QAReviewResponse(q.getId(),b.getId(),b.getBatchNumber(),b.getProduct().getProductCode(),b.getProduct().getProductName(),q.getReviewerId(),q.getReviewType(),q.getDecision(),q.getReviewDate(),q.getComments());}
}
